def execute_install(self):
    """Install roles and/or collections from a requirements file or names."""
    galaxy_type = context.CLIARGS['type']
    role_file = context.CLIARGS['role_file']
    requirements_file = context.CLIARGS['requirements'] if galaxy_type == 'collection' else role_file
    names = context.CLIARGS['args']

    if galaxy_type == 'collection':
        if names and requirements_file:
            raise AnsibleError("The positional collection_name arg and --requirements-file are mutually exclusive.")
        if not names and not requirements_file:
            raise AnsibleError("You must specify a collection name or a requirements file.")
    elif not names and not requirements_file:
        raise AnsibleOptionsError("- you must specify a user/role name or a roles file")

    if role_file and not role_file.endswith(('.yml', '.yaml')):
        raise AnsibleError("Invalid role requirements file, it must end with a .yml or .yaml extension")

    if requirements_file:
        requirements_file = GalaxyCLI._resolve_path(requirements_file)
        requirements = self._parse_requirements_file(requirements_file, allow_old_format=(galaxy_type == 'role'))
    elif galaxy_type == 'collection':
        requirements = {'roles': [], 'collections': self._require_one_of_collections_requirements(names, None)}
    else:
        requirements = {'roles': [], 'collections': []}
        for name in names:
            role = RoleRequirement.role_yaml_parse(name.strip())
            requirements['roles'].append(GalaxyRole(self.galaxy, self.api, **role))

    install_roles = galaxy_type == 'role' and bool(requirements['roles'])
    install_collections_now = (galaxy_type == 'collection' or
                               (self._implicit_role and not self._custom_roles_path)) and bool(requirements['collections'])

    if requirements['collections'] and not install_collections_now:
        message = ("The requirements file '%s' contains collections which will be ignored. "
                   "To install these collections run 'ansible-galaxy collection install -r' or to install both "
                   "at the same time run 'ansible-galaxy install -r' without a custom install path." % requirements_file)
        if self._custom_roles_path:
            message = "Collections cannot be installed to a roles path. " + message
            if self._implicit_role:
                display.warning(message)
            else:
                display.vvv(message)
        else:
            display.display(message)
    if requirements['roles'] and not install_roles:
        display.display("The requirements file '%s' contains roles which will be ignored. "
                        "To install these roles run 'ansible-galaxy role install -r' or to install both "
                        "at the same time run 'ansible-galaxy install -r' without a custom install path."
                        % requirements_file)

    if not install_roles and not install_collections_now:
        if not requirements['roles'] and not requirements['collections']:
            display.display('Skipping install, no requirements found')
        return 0

    if install_roles:
        display.display('Starting galaxy role install process')
        self._install_roles(requirements['roles'], role_file)
    if install_collections_now:
        display.display('Starting galaxy collection install process')
        self._install_collections(requirements['collections'])
    return 0

